from pathlib import Path
import ezdxf
p=Path('part.dxf')
doc=ezdxf.readfile(p)
print('version',doc.dxfversion,'units',doc.units)
for layout in doc.layouts:
    print('\\nLAYOUT',layout.name)
    for e in layout:
        print(e.dxftype(), e.dxf.handle, e.dxfattribs())
        if e.dxftype()=='LWPOLYLINE': print('  points',list(e.get_points()))
        if e.dxftype() in ('TEXT','MTEXT'): print('  text', e.dxf.get('text', '') if e.dxftype()=='TEXT' else e.text)
print('\\nBLOCKS')
for b in doc.blocks:
    if b.name.startswith('*Model') or b.name.startswith('*Paper'): continue
    print('BLOCK',b.name,'base',b.block.dxf.base_point)
    for e in b:
        print(' ',e.dxftype(),e.dxf.handle,e.dxfattribs())
        if e.dxftype()=='LWPOLYLINE': print('  points',list(e.get_points()))
print('APPIDS',list(doc.appids.entries))
